src/Controller/Webauthn/RegisterOptionsController.php<pre><code>&lt;?php

declare(strict_types=1);

namespace App\Controller\Webauthn;

use App\Security\NewUserEntityGuesser;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\Routing\Attribute\Route;
use Webauthn\Bundle\Service\WebauthnOptionsResponse;

final class RegisterOptionsController
{
    public function __construct(
        private readonly WebauthnOptionsResponse $options,
        private readonly NewUserEntityGuesser $guesser,
    ) {
    }

    #[Route('/webauthn/register/options', methods: ['POST'])]
    public function __invoke(Request $request): JsonResponse
    {
        return $this-&gt;options
            -&gt;forCreation('example.com', $this-&gt;guesser)
            -&gt;build($request);
    }
}
</code></pre> <p><code>NewUserEntityGuesser</code> is a class you write that implements <code>Webauthn\Bundle\Security\Guesser\UserEntityGuesser</code>. It reads the username from the body, generates a user handle, and returns a <code>PublicKeyCredentialUserEntity</code>. The bundle does not ship a generic implementation: that logic is application-specific.</p>

src/Controller/Webauthn/LoginOptionsController.php<pre><code>#[Route('/webauthn/login/options', methods: ['POST'])]
public function __invoke(Request $request): JsonResponse
{
    return $this-&gt;options
        -&gt;forRequest('example.com')
        -&gt;build($request);
}
</code></pre> <p>No guesser, no allow-list. The user agent will offer the user any platform-side discoverable passkey for <code>example.com</code>.</p>

src/Controller/Webauthn/RegisterResponseController.php<pre><code>&lt;?php

declare(strict_types=1);

namespace App\Controller\Webauthn;

use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\Routing\Attribute\Route;
use Webauthn\Bundle\Security\Authentication\Exception\WebauthnAuthenticationFailureException;
use Webauthn\Bundle\Service\WebauthnResponseVerifier;

final class RegisterResponseController
{
    public function __construct(
        private readonly WebauthnResponseVerifier $verifier,
    ) {
    }

    #[Route('/webauthn/register', methods: ['POST'])]
    public function __invoke(Request $request): JsonResponse
    {
        try {
            $result = $this-&gt;verifier
                -&gt;forAttestation('example.com')
                -&gt;verify($request);
        } catch (WebauthnAuthenticationFailureException $exception) {
            return new JsonResponse(['error' =&gt; $exception-&gt;getMessage()], 401);
        }

        return new JsonResponse([
            'status' =&gt; 'registered',
            'credentialId' =&gt; base64_encode($result-&gt;credentialRecord-&gt;publicKeyCredentialId),
        ]);
    }
}
</code></pre>

src/Controller/Webauthn/LoginResponseController.php<pre><code>#[Route('/webauthn/login', methods: ['POST'])]
public function __invoke(Request $request): Response
{
    try {
        $result = $this-&gt;verifier
            -&gt;forAssertion('example.com')
            -&gt;verify($request);
    } catch (WebauthnAuthenticationFailureException $exception) {
        return new JsonResponse(['error' =&gt; $exception-&gt;getMessage()], 401);
    }

    // Log the user in. Up to you: WebauthnToken, your own UserChecker, etc.
    $this-&gt;loginUser($result-&gt;credentialRecord, $result-&gt;userEntity);

    return new JsonResponse(['status' =&gt; 'authenticated']);
}
</code></pre> <p><code>allowCredentials</code>, the user handle, the host and the challenge are all checked under the hood through the underlying validators and ceremony steps. Nothing else to wire on the controller side.</p>

